\n  String _searchQuery = '';\n  bool _isFirstBuild = true;\n  late final ShowcaseView _showcaseView;\n  final GlobalKey _createDiaryShowcaseKey = GlobalKey(\n    debugLabel: 'diaries_create_diary_showcase',\n  );\n  bool _isCreateDiaryShowcaseRunning = false;\n\n  @override\n  void initState() {\n    super.initState();\n    _showcaseView = ShowcaseView.register(\n      scope: 'diaries_showcase',\n      onComplete: (_, key) {\n        if (key == _createDiaryShowcaseKey) {\n          _dismissCreateDiaryHintIfVisible();\n          _isCreateDiaryShowcaseRunning = false;\n        }\n      },\n      onDismiss: (_) {\n        _dismissCreateDiaryHintIfVisible();\n        _isCreateDiaryShowcaseRunning = false;\n      },\n    );\n    // \u041f\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u043c \u043c\u043e\u0434\u0430\u043b\u044c\u043d\u043e\u0435 \u043e\u043a\u043d\u043e \u0434\u043b\u044f \u0432\u0435\u0431-\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u0435\u043b\u0435\u0439\n    WidgetsBinding.instance.addPostFrameCallback((_) {\n      DownloadAppModal.showIfWeb(context);\n      if (widget.showCreateDiaryHint && mounted) {\n        context.read<HintBloc>().add(\n          const HintShowRequested(HintIds.diariesCreateDiary),\n        );\n      }\n    });\n  }\n\n  @override\n  void didChangeDependencies() {\n    super.didChangeDependencies();\n    // \u041f\u0435\u0440\u0435\u0437\u0430\u0433\u0440\u0443\u0436\u0430\u0435\u043c \u0441\u043f\u0438\u0441\u043e\u043a \u0434\u043d\u0435\u0432\u043d\u0438\u043a\u043e\u0432 \u043f\u0440\u0438 \u043a\u0430\u0436\u0434\u043e\u043c \u0432\u043e\u0437\u0432\u0440\u0430\u0442\u0435 \u043d\u0430 \u0441\u0442\u0440\u0430\u043d\u0438\u0446\u0443 (\u043a\u0440\u043e\u043c\u0435 \u043f\u0435\u0440\u0432\u043e\u0433\u043e \u0440\u0430\u0437\u0430)\n    if (!_isFirstBuild) {\n      context.read<DiaryBloc>().add(const LoadDiaries());\n    }\n    _isFirstBuild = false;\n  }\n\n  @override\n  void dispose() {\n    _showcaseView.unregister();\n    _searchController.dispose();\n    super.dispose();\n  }\n\n  void _dismissCreateDiaryHintIfVisible() {\n    if (context.read<HintBloc>().state.isHintVisible(\n      HintIds.diariesCreateDiary,\n    )) {\n      context.read<HintBloc>().add(\n        const HintDismissRequested(HintIds.diariesCreateDiary),\n      );\n    }\n  }\n\n  List<Diary> _filterDiaries(List<Diary> diaries) {\n    if (_searchQuery.isEmpty) {\n      return diaries;\n    }\n    return diaries.where((diary) {\n      return diary.patientName.toLowerCase().contains(\n        _searchQuery.toLowerCase(),\n      );\n    }).toList();\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    final hintState = context.watch<HintBloc>().state;\n    final isCreateDiaryHintVisible = hintState.isHintVisible(\n      HintIds.diariesCreateDiary,\n    );\n\n    if (isCreateDiaryHintVisible && !_isCreateDiaryShowcaseRunning) {\n      WidgetsBinding.instance.addPostFrameCallback((_) {\n        if (!mounted) return;\n        _showcaseView.startShowCase([_createDiaryShowcaseKey]);\n      });\n      _isCreateDiaryShowcaseRunning = true;\n    } else if (!isCreateDiaryHintVisible && _isCreateDiaryShowcaseRunning) {\n      WidgetsBinding.instance.addPostFrameCallback((_) {\n        if (!mounted) return;\n        _showcaseView.dismiss();\n      });\n      _isCreateDiaryShowcaseRunning = false;\n    }\n\n    return Scaffold(\n          backgroundColor: const Color(0xFFF7F7F8),\n          appBar: AppBar(\n            backgroundColor: Colors.transparent,\n            elevation: 0,\n            centerTitle: false,\n            automaticallyImplyLeading: false,\n            title: Text(\n              '\u041c\u043e\u0438 \u0434\u043d\u0435\u0432\u043d\u0438\u043a\u0438',\n              style: GoogleFonts.firaSans(\n                fontSize: 20,\n                fontWeight: FontWeight.w900,\n                color: Colors.grey.shade900,\n              ),\n            ),\n            actions: [\n              Padding(\n                padding: const EdgeInsets.only(right: 16),\n                child: GestureDetector(\n                  onTap: () => context.push('/profile'),\n                  child: BlocBuilder<AuthBloc, AuthState>(\n                    builder: (context, authState) {\n                      String? avatarUrl;\n                      if (authState is AuthAuthenticated) {\n                        avatarUrl = authState.user.avatar;\n                      }\n                      return _buildAvatar(avatarUrl);\n                    },\n                  ),\n                ),\n              ),\n              Text(\n                '\u041f\u0440\u043e\u0444\u0438\u043b\u044c',\n                style: GoogleFonts.firaSans(\n                  fontSize: 15,\n                  fontWeight: FontWeight.w500,\n                  color: Colors.grey.shade900,\n                ),\n              ),\n              const SizedBox(width: 16),\n            ],\n          ),\n          body: SafeArea(\n            child: Column(\n              children: [\n                Padding(\n                  padding: const EdgeInsets.fromLTRB(16, 8, 16, 8),\n                  child: TextField(\n                    controller: _searchController,\n                    style: GoogleFonts.firaSans(\n                      fontSize: 18,\n                      color: Colors.grey.shade800,\n                    ),\n                    decoration: InputDecoration(\n                      hintText: '\u041f\u043e\u0438\u0441\u043a \u043f\u043e \u0438\u043c\u0435\u043d\u0438 \u043f\u043e\u0434\u043e\u043f\u0435\u0447\u043d\u043e\u0433\u043e...',\n                      hintStyle: GoogleFonts.firaSans(\n                        fontSize: 18,\n                        color: Colors.grey.shade400,\n                      ),\n                      suffixIcon: _searchQuery.isNotEmpty\n                          ? IconButton(\n                              icon: Icon(\n                                Icons.clear,\n                                color: Colors.grey.shade400,\n                              ),\n                              onPressed: () {\n                                setState(() {\n                                  _searchController.clear();\n                                  _searchQuery = '';\n                                });\n                              },\n                            )\n                          : null,\n                      filled: true,\n                      fillColor: const Color(0xFFF7F7F8),\n                      contentPadding: const EdgeInsets.symmetric(\n                        vertical: 12,\n                        horizontal: 16,\n                      ),\n                      border: InputBorder.none,\n                      enabledBorder: InputBorder.none,\n                      focusedBorder: InputBorder.none,\n                    ),\n                    onChanged: (value) {\n                      setState(() {\n                        _searchQuery = value;\n                      });\n                    },\n                  ),\n                ),\n                Expanded(\n                  child: BlocBuilder<DiaryBloc, DiaryState>(\n                    buildWhen: (previous, current) {\n                      return previous.runtimeType != current.runtimeType ||\n                          (previous is DiariesLoaded &&\n                              current is DiariesLoaded &&\n                              previous.diaries.length !=\n                                  current.diaries.length);\n                    },\n                    builder: (context, state) {\n                      if (state is DiaryLoading) {\n                        return _buildShimmerLoading();\n                      }\n\n                      if (state is DiaryError) {\n                        return _buildErrorState(context, state.message);\n                      }\n\n                      if (state is DiariesLoaded) {\n                        final filteredDiaries = _filterDiaries(state.diaries);\n\n                        if (state.diaries.isEmpty) {\n                          return _buildEmptyState();\n                        }\n\n                        if (filteredDiaries.isEmpty &&\n                            _searchQuery.isNotEmpty) {\n                          return _buildNoResultsState();\n                        }\n\n                        return _buildDiariesList(context, filteredDiaries);\n                      }\n\n                      return _buildEmptyState();\n                    },\n                  ),\n                ),\n                BlocBuilder<AuthBloc, AuthState>(\n                  builder: (context, authState) {\n                    bool canCreateDiary = true;\n                    if (authState is AuthAuthenticated) {\n                      final type = authState.user.accountType;\n                      if (type == 'specialist' ||\n                          type == 'doctor' ||\n                          type == 'caregiver') {\n                        canCreateDiary = false;\n                      }\n                    }\n\n                    if (!canCreateDiary) return const SizedBox.shrink();\n\n                    return Padding(\n                      padding: const EdgeInsets.all(16),\n                      child: SizedBox(\n                        width: double.infinity,\n                        child: ElevatedButton(\n                          style: ElevatedButton.styleFrom(\n                            backgroundColor: AppConfig.primaryColor,\n                            padding: const EdgeInsets.symmetric(vertical: 16),\n                            shape: RoundedRectangleBorder(\n                              borderRadius: BorderRadius.circular(14),\n                            ),\n                            elevation: 0,\n                          ),\n                          onPressed: () {\n                            if (isCreateDiaryHintVisible) {\n                              _dismissCreateDiaryHintIfVisible();\n                            }\n                            context.push('/select-ward-for-diary');\n                          },\n                          child: Row(\n                            mainAxisAlignment: MainAxisAlignment.center,\n                            children: [\n                              const Icon(\n                                Icons.add,\n                                color: Colors.white,\n                                size: 20,\n                              ),\n                              const SizedBox(width: 8),\n                              Text(\n                                '\u0421\u043e\u0437\u0434\u0430\u0442\u044c \u043d\u043e\u0432\u044b\u0439 \u0434\u043d\u0435\u0432\u043d\u0438\u043a',\n                                style: GoogleFonts.firaSans(\n                                  fontSize: 16,\n                                  fontWeight: FontWeight.w700,\n                                  color: Colors.white,\n                                ),\n                              ),\n                            ],\n                          ),\n                        ),\n                      ),\n                    );\n                  },\n                ),\n              ],\n            ),\n          ),\n        ),\n        if (isCreateDiaryHintVisible)\n          const Positioned.fill(child: _CreateDiaryHintOverlay()),\n      ],\n    );\n  }\n\n  Widget _buildShimmerLoading() {\n    return ListView.builder(\n      padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 8),\n      itemCount: 5,\n      itemBuilder: (context, index) {\n        return Container(\n          margin: const EdgeInsets.only(bottom: 12),\n          decoration: BoxDecoration(\n            color: Colors.white,\n            borderRadius: BorderRadius.circular(16),\n            boxShadow: [\n              BoxShadow(\n                color: Colors.black.withValues(alpha: 0.05),\n                blurRadius: 10,\n                offset: const Offset(0, 2),\n              ),\n            ],\n          ),\n          child: Shimmer.fromColors(\n            baseColor: Colors.grey.shade300,\n            highlightColor: Colors.grey.shade100,\n            child: Padding(\n              padding: const EdgeInsets.all(16),\n              child: Row(\n                children: [\n                  Expanded(\n                    child: Column(\n                      crossAxisAlignment: CrossAxisAlignment.start,\n                      children: [\n                        Container(\n                          width: 150,\n                          height: 16,\n                          decoration: BoxDecoration(\n                            color: Colors.white,\n                            borderRadius: BorderRadius.circular(4),\n                          ),\n                        ),\n                        const SizedBox(height: 8),\n                        Container(\n                          width: 80,\n                          height: 12,\n                          decoration: BoxDecoration(\n                            color: Colors.white,\n                            borderRadius: BorderRadius.circular(4),\n                          ),\n                        ),\n                      ],\n                    ),\n                  ),\n                  Container(\n                    width: 20,\n                    height: 20,\n                    decoration: BoxDecoration(\n                      color: Colors.white,\n                      borderRadius: BorderRadius.circular(4),\n                    ),\n                  ),\n                ],\n              ),\n            ),\n          ),\n        );\n      },\n    );\n  }\n\n  Widget _buildEmptyState() {\n    return Center(\n      child: Padding(\n        padding: const EdgeInsets.symmetric(horizontal: 32),\n        child: Column(\n          mainAxisAlignment: MainAxisAlignment.center,\n          children: [\n            // Central icon with gradient\n            Container(\n              width: 120,\n              height: 120,\n              decoration: BoxDecoration(\n                shape: BoxShape.circle,\n                gradient: LinearGradient(\n                  colors: [\n                    AppConfig.primaryColor.withValues(alpha: 0.7),\n                    AppConfig.primaryColor,\n                  ],\n                  begin: Alignment.topLeft,\n                  end: Alignment.bottomRight,\n                ),\n              ),\n              child: const Icon(\n                Icons.description_outlined,\n                size: 64,\n                color: Colors.white,\n              ),\n            ),\n            const SizedBox(height: 32),\n\n            // Primary message\n            Text(\n              '\u0423 \u0432\u0430\u0441 \u043f\u043e\u043a\u0430 \u043d\u0435\u0442 \u0434\u043d\u0435\u0432\u043d\u0438\u043a\u043e\u0432',\n              style: GoogleFonts.firaSans(\n                fontSize: 18,\n                fontWeight: FontWeight.w700,\n                color: Colors.grey.shade900,\n              ),\n              textAlign: TextAlign.center,\n            ),\n            const SizedBox(height: 12),\n\n            // Secondary message\n            Text(\n              '\u0421\u043e\u0437\u0434\u0430\u0439\u0442\u0435 \u043f\u0435\u0440\u0432\u044b\u0439 \u0434\u043d\u0435\u0432\u043d\u0438\u043a \u0434\u043b\u044f \u043f\u043e\u0434\u043e\u043f\u0435\u0447\u043d\u043e\u0433\u043e',\n              style: GoogleFonts.firaSans(\n                fontSize: 14,\n                color: Colors.grey.shade700,\n              ),\n              textAlign: TextAlign.center,\n            ),\n          ],\n        ),\n      ),\n    );\n  }\n\n  Widget _buildNoResultsState() {\n    return Center(\n      child: Padding(\n        padding: const EdgeInsets.symmetric(horizontal: 32),\n        child: Column(\n          mainAxisAlignment: MainAxisAlignment.center,\n          children: [\n            Icon(Icons.search_off, size: 80, color: Colors.grey.shade300),\n            const SizedBox(height: 24),\n            Text(\n              '\u041d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u043d\u0430\u0439\u0434\u0435\u043d\u043e',\n              style: GoogleFonts.firaSans(\n                fontSize: 18,\n                fontWeight: FontWeight.w700,\n                color: Colors.grey.shade900,\n              ),\n              textAlign: TextAlign.center,\n            ),\n            const SizedBox(height: 12),\n            Text(\n              '\u041f\u043e\u043f\u0440\u043e\u0431\u0443\u0439\u0442\u0435 \u0438\u0437\u043c\u0435\u043d\u0438\u0442\u044c \u043f\u043e\u0438\u0441\u043a\u043e\u0432\u044b\u0439 \u0437\u0430\u043f\u0440\u043e\u0441',\n              style: GoogleFonts.firaSans(\n                fontSize: 14,\n                color: Colors.grey.shade600,\n              ),\n              textAlign: TextAlign.center,\n            ),\n          ],\n        ),\n      ),\n    );\n  }\n\n  Widget _buildErrorState(BuildContext context, String message) {\n    return Center(\n      child: Padding(\n        padding: const EdgeInsets.symmetric(horizontal: 32),\n        child: Column(\n          mainAxisAlignment: MainAxisAlignment.center,\n          children: [\n            Icon(Icons.error_outline, size: 64, color: Colors.red.shade400),\n            const SizedBox(height: 16),\n            Text(\n              message,\n              style: GoogleFonts.firaSans(\n                fontSize: 16,\n                color: Colors.grey.shade700,\n              ),\n              textAlign: TextAlign.center,\n            ),\n            const SizedBox(height: 24),\n            ElevatedButton(\n              onPressed: () {\n                context.read<DiaryBloc>().add(const LoadDiaries());\n              },\n              style: ElevatedButton.styleFrom(\n                backgroundColor: AppConfig.primaryColor,\n              ),\n              child: Text(\n                '\u041f\u043e\u0432\u0442\u043e\u0440\u0438\u0442\u044c',\n                style: GoogleFonts.firaSans(\n                  fontWeight: FontWeight.w600,\n                  color: Colors.white,\n                ),\n              ),\n            ),\n          ],\n        ),\n      ),\n    );\n  }\n\n  Widget _buildDiariesList(BuildContext context, List<Diary> diaries) {\n    return RefreshIndicator(\n      onRefresh: () async {\n        context.read<DiaryBloc>().add(const LoadDiaries());\n      },\n      child: OptimizedListView(\n        itemCount: diaries.length,\n        padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 8),\n        itemBuilder: (context, index) {\n          final diary = diaries[index];\n          return OptimizedWidget(child: _DiaryCard(diary: diary));\n        },\n      ),\n    );\n  }\n\n  /// \u0412\u0438\u0434\u0436\u0435\u0442 \u0434\u043b\u044f \u043e\u0442\u043e\u0431\u0440\u0430\u0436\u0435\u043d\u0438\u044f \u0430\u0432\u0430\u0442\u0430\u0440\u0430 \u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u0435\u043b\u044f\n  Widget _buildAvatar(String? avatarUrl) {\n    if (avatarUrl != null && avatarUrl.isNotEmpty) {\n      // \u041f\u0440\u0435\u043e\u0431\u0440\u0430\u0437\u0443\u0435\u043c \u043e\u0442\u043d\u043e\u0441\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0439 \u043f\u0443\u0442\u044c \u0432 \u043f\u043e\u043b\u043d\u044b\u0439 URL\n      final fullUrl = ApiConfig.getFullUrl(avatarUrl);\n\n      return ClipOval(\n        child: CachedNetworkImage(\n          imageUrl: fullUrl,\n          width: 44,\n          height: 44,\n          fit: BoxFit.cover,\n          placeholder: (context, url) => Container(\n            width: 44,\n            height: 44,\n            decoration: BoxDecoration(\n              color: Colors.grey.shade200,\n              shape: BoxShape.circle,\n            ),\n            child: Center(\n              child: CircularProgressIndicator(\n                color: AppConfig.primaryColor,\n                strokeWidth: 2,\n              ),\n            ),\n          ),\n          errorWidget: (context, url, error) => Container(\n            width: 44,\n            height: 44,\n            decoration: BoxDecoration(\n              color: Colors.grey.shade200,\n              shape: BoxShape.circle,\n            ),\n            child: Center(\n              child: SvgPicture.asset(\n                AppIcons.profile,\n                width: 44,\n                height: 44,\n                fit: BoxFit.contain,\n              ),\n            ),\n          ),\n        ),\n      );\n    }\n\n    return SizedBox(\n      width: 44,\n      height: 44,\n      child: Center(\n        child: SvgPicture.asset(\n          AppIcons.profile,\n          width: 44,\n          height: 44,\n          fit: BoxFit.contain,\n        ),\n      ),\n    );\n  }\n}\n\nclass _CreateDiaryHintTooltip extends StatelessWidget {\n  const _CreateDiaryHintTooltip();\n\n  @override\n  Widget build(BuildContext context) {\n    final tooltipWidth = (MediaQuery.sizeOf(context).width - 32).clamp(\n      280.0,\n      430.0,\n    );\n\n    return MediaQuery(\n      data: MediaQuery.of(context).copyWith(textScaler: TextScaler.noScaling),\n      child: SizedBox(\n        width: tooltipWidth,\n        child: Container(\n          padding: const EdgeInsets.fromLTRB(22, 28, 22, 34),\n          decoration: BoxDecoration(\n            gradient: const LinearGradient(\n              begin: Alignment.topLeft,\n              end: Alignment.bottomRight,\n              colors: [Color(0xFF7FC7DA), Color(0xFF3E8FA5)],\n            ),\n            borderRadius: BorderRadius.circular(32),\n          ),\n          child: Column(\n            mainAxisSize: MainAxisSize.min,\n            crossAxisAlignment: CrossAxisAlignment.center,\n            children: [\n              Text(\n                '\u0421\u043e\u0437\u0434\u0430\u0434\u0438\u043c \u0434\u043d\u0435\u0432\u043d\u0438\u043a\\n\u0437\u0434\u043e\u0440\u043e\u0432\u044c\u044f',\n                textAlign: TextAlign.center,\n                style: GoogleFonts.firaSans(\n                  fontSize: 24,\n                  fontWeight: FontWeight.w900,\n                  color: Colors.white,\n                  height: 1.1,\n                  decoration: TextDecoration.none,\n                ),\n              ),\n              const SizedBox(height: 28),\n              Text(\n                '\u0412 \u0434\u043d\u0435\u0432\u043d\u0438\u043a\u0435 \u0432\u044b \u0431\u0443\u0434\u0435\u0442\u0435:\\n'\n                ' \u2022 \u0437\u0430\u043f\u0438\u0441\u044b\u0432\u0430\u0442\u044c \u0441\u043e\u0441\u0442\u043e\u044f\u043d\u0438\u0435\\n'\n                ' \u2022 \u043e\u0442\u043c\u0435\u0447\u0430\u0442\u044c \u043f\u0440\u043e\u0446\u0435\u0434\u0443\u0440\u044b\\n'\n                ' \u2022 \u0441\u043b\u0435\u0434\u0438\u0442\u044c \u0437\u0430 \u0437\u0434\u043e\u0440\u043e\u0432\u044c\u0435\u043c\\n'\n                ' \u2022 \u0434\u0435\u043b\u0438\u0442\u044c\u0441\u044f \u0434\u043e\u0441\u0442\u0443\u043f\u043e\u043c \u0441 \u0441\u0438\u0434\u0435\u043b\u043a\u0430\u043c\u0438\\n'\n                '   \u0438\u043b\u0438 \u0440\u043e\u0434\u0441\u0442\u0432\u0435\u043d\u043d\u0438\u043a\u0430\u043c\u0438',\n                style: GoogleFonts.firaSans(\n                  fontSize: 16,\n                  fontWeight: FontWeight.w600,\n                  color: Colors.white,\n                  height: 1.35,\n                  decoration: TextDecoration.none,\n                ),\n              ),\n              const SizedBox(height: 72),\n              Center(\n                child: Text(\n                  '\u041d\u0430\u0436\u043c\u0438\u0442\u0435 \u043d\u0430 \u043a\u043d\u043e\u043f\u043a\u0443 \u043d\u0438\u0436\u0435',\n                  textAlign: TextAlign.center,\n                  style: GoogleFonts.firaSans(\n                    fontSize: 18,\n                    fontWeight: FontWeight.w900,\n                    color: Colors.white,\n                    decoration: TextDecoration.none,\n                  ),\n                ),\n              ),\n            ],\n          ),\n        ),\n      ),\n    );\n  }\n}\n\nclass _CreateDiaryHintOverlay extends StatelessWidget {\n  const _CreateDiaryHintOverlay();\n\n  @override\n  Widget build(BuildContext context) {\n    return IgnorePointer(\n      ignoring: true,\n      child: Stack(\n        children: [\n          ColoredBox(color: Colors.black.withValues(alpha: 0.58)),\n          SafeArea(\n            child: Padding(\n              padding: const EdgeInsets.fromLTRB(16, 72, 16, 110),\n              child: Align(\n                alignment: Alignment.topCenter,\n                child: const _CreateDiaryHintTooltip(),\n              ),\n            ),\n          ),\n        ],\n      ),\n    );\n  }\n}\n\nclass _DiaryCard extends StatelessWidget {\n  final Diary diary;\n\n  const _DiaryCard({required this.diary});\n\n  @override\n  Widget build(BuildContext context) {\n    return Container(\n      margin: const EdgeInsets.only(bottom: 12),\n      decoration: BoxDecoration(\n        color: Colors.white,\n        borderRadius: BorderRadius.circular(16),\n        boxShadow: [\n          BoxShadow(\n            color: Colors.black.withValues(alpha: 0.05),\n            blurRadius: 10,\n            offset: const Offset(0, 2),\n          ),\n        ],\n      ),\n      child: Material(\n        color: Colors.transparent,\n        child: InkWell(\n          borderRadius: BorderRadius.circular(16),\n          onTap: () {\n            context.push('/health-diary/${diary.id}/${diary.patientId}');\n          },\n          child: Padding(\n            padding: const EdgeInsets.all(16),\n            child: Column(\n              crossAxisAlignment: CrossAxisAlignment.start,\n              children: [\n                // Header row with patient name and arrow\